package com.asmj.marketplace.review.controller;import com.asmj.marketplace.review.model.Review;import com.asmj.marketplace.review.service.ReviewService;import com.asmj.marketplace.common.response.ApiResponse;import lombok.RequiredArgsConstructor;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController@RequestMapping("/api/reviews")@RequiredArgsConstructor public class ReviewController{private final ReviewService s;@PostMapping public ApiResponse<Review> add(Authentication a,@RequestParam String postId,@RequestParam int rating,@RequestParam(required=false)String comment){return ApiResponse.ok("Review added",s.add(a.getName(),postId,rating,comment));}@GetMapping("/post/{postId}")public ApiResponse<List<Review>> byPost(@PathVariable String postId){return ApiResponse.ok("Reviews",s.byPost(postId));}}
